mapper.select:
SELECT a.id, a.user_id AS userId, u.phone, u.real_name AS realName, p.name AS packageName, s.appoint_date AS appointDate, s.time_range AS timeRange, a.status, a.report_url AS reportUrl, a.create_time AS createTime FROM appointment a LEFT JOIN user u ON a.user_id = u.id LEFT JOIN appointment_package p ON a.package_id = p.id LEFT JOIN appointment_slot s ON a.slot_id = s.id WHERE a.deleted = 0
AND a.status = #{status}
ORDER BY a.id ASC
